<header class="page-header"><div><p class="eyebrow">Commercial pipeline</p><h1>Opportunities</h1></div></header>
<form class="filter-bar" method="get" action="<?= $escape($indexUrl) ?>"><label>Search<input name="q" value="<?= $escape($filters['q']) ?>"></label><label>Stage<select name="stage"><option value="">All stages</option><?php foreach($stages as $key=>$label): ?><option value="<?= $escape($key) ?>"<?= $filters['stage']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label><label>Offer<select name="offer"><option value="">All offers</option><?php foreach($offers as $key=>$label): ?><option value="<?= $escape($key) ?>"<?= $filters['offer']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label><label>Sort<select name="sort"><?php foreach(['updated'=>'Recently updated','expected_close'=>'Expected close','value'=>'Value','stage'=>'Stage'] as $key=>$label): ?><option value="<?= $escape($key) ?>"<?= $filters['sort']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label><label>Direction<select name="direction"><option value="desc"<?= $filters['direction']==='desc'?' selected':'' ?>>Descending</option><option value="asc"<?= $filters['direction']==='asc'?' selected':'' ?>>Ascending</option></select></label><button>Apply</button><a href="<?= $escape($indexUrl) ?>">Clear</a></form>
<p><?= $escape($count) ?> result<?= $count===1?'':'s' ?>.</p><?php if($opportunities===[]): ?><section class="empty-state"><h2><?= $count === 0 && ($filters['q'] !== '' || $filters['stage'] !== '' || $filters['offer'] !== '') ? 'No matching opportunities' : 'No opportunities yet' ?></h2><p>Qualify a prospect before adding one.</p></section><?php else: ?><div class="table-scroll"><table><thead><tr><th>Relationship</th><th>Stage</th><th>Value</th><th>Expected close</th><th>Next action</th></tr></thead><tbody><?php foreach($opportunities as $o): ?><tr><td><a href="<?= $escape($showUrl((int)$o['id'])) ?>"><?= $escape($o['company_name']?:$o['contact_name']) ?></a></td><td><?= $escape($stages[$o['stage']]??$o['stage']) ?></td><td>$<?= $escape($o['value_amount']) ?></td><td><?= $escape($o['expected_close_on']??'—') ?></td><td><?= $escape($o['follow_up_action']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if($pages>1): ?><nav class="pagination" aria-label="Opportunity pages"><?php for($number=1;$number<=$pages;$number++): ?><a href="<?= $escape($indexUrl.'?'.http_build_query($filters+['page'=>$number])) ?>"<?= $number===$page?' aria-current="page"':'' ?>><?= $escape($number) ?></a><?php endfor; ?></nav><?php endif; ?>
